    "ff196cc6a4486bc534147d5cb82c6f6328893f546c410afa81a1432ac5b3a3d9": {
      "input_schema": {
        "type": "object",
        "properties": {
          "sendType": {
            "type": "integer",
            "minimum": -2147483648,
            "maximum": 2147483647,
            "description": "SendType,enumerated as follows: \n0:All the products in one parent order are shipped in one package with one tracking number\n1:Partical products in one parent order are shipped in multiple packages with multiple tracking numbers and all the products in one order should be shipped in one API call.\n2:All the products in multiple parent orders are shipped in one package with one tracking number."
          },
          "sendRequestList": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "carrierId": {
                  "type": "integer",
                  "minimum": -9007199254740991,
                  "maximum": 9007199254740991,
                  "description": "Carrier ID, it's the same ID with the logisticsServiceProviderId you got from \"bg.logistics.companies.get\"."
                },
                "trackingNumber": {
                  "type": "string",
                  "description": "Tracking Number."
                },
                "selfShippingWarehouseId": {
                  "type": "string",
                  "description": "The shipment warehouse ID can be obtained from the bg.logistics.warehouse.list.get interface."
                },
                "orderSendInfoList": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
                      "parentOrderSn": {
                        "type": "string",
                        "description": "Parent Order Number."
                      },
                      "orderSn": {
                        "type": "string",
                        "description": "Order Number."
                      },
                      "goodsId": {
                        "type": "integer",
                        "minimum": -9007199254740991,
                        "maximum": 9007199254740991,
                        "description": "Goods ID."
                      },
                      "skuId": {
                        "type": "integer",
                        "minimum": -9007199254740991,
                        "maximum": 9007199254740991,
                        "description": "SKU ID."
                      },
                      "quantity": {
                        "type": "integer",
                        "minimum": -2147483648,
                        "maximum": 2147483647,
                        "description": "Quantity of the product."
                      }
                    },
                    "required": [
                      "parentOrderSn",
                      "orderSn",
                      "quantity"
                    ],
                    "additionalProperties": false
                  },
                  "description": "Product List in this package."
                },
                "confirmAcceptance": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "Confirmation matters for this shipment,enumerated as follows: \nDENY_CANCELLATION: Reject the cancellation request for this order;\nDENY_ADDRESS_CHANGE: Reject the address change request for this order.\nDENY_PARENT_RISK_WARNING:Reject the risk warning for this order."
                },
                "subSendRequests": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
                      "carrierId": {
                        "type": "integer",
                        "minimum": -9007199254740991,
                        "maximum": 9007199254740991,
                        "description": "Logistics Company ID"
                      },
                      "trackingNumber": {
                        "type": "string",
                        "description": "Waybill Number"
                      },
                      "selfShippingWarehouseId": {
                        "type": "string",
                        "description": "Self-Delivery Warehouse ID"
                      }
                    },
                    "required": [
                      "carrierId",
                      "trackingNumber",
                      "selfShippingWarehouseId"
                    ],
                    "additionalProperties": false
                  },
                  "description": "Sub Send Requests"
                }
              },
              "required": [
                "carrierId",
                "selfShippingWarehouseId",
                "orderSendInfoList"
              ],
              "additionalProperties": false
            },
            "description": "Shipment package details"
          }
        },
        "required": [
          "sendType",
          "sendRequestList"
        ],
        "additionalProperties": false
      },
      "result_type": "OBJECT",
      "allow_absent_result": false
    },
